// This code has been fully generated by an AI.

// Command fitinspect summarizes FIT activity files and reports which files
// describe the same recording. It accepts FIT files, directories and ZIP
// archives such as the Garmin Connect bulk export.
//
//	fitinspect [-json] <path>...
package main

import (
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"sort"
	"text/tabwriter"

	"github.com/stefanluchs/my-velo/internal/fitfile"
)

type entry struct {
	Source string `json:"source"`
	// Skipped marks valid FIT files that are no activities (monitoring, sleep …).
	Skipped bool `json:"skipped,omitempty"`
	// FileNumber is the number in the file name (Garmin export: upload file
	// number, not the activity ID).
	FileNumber string           `json:"file_number,omitempty"`
	Summary    *fitfile.Summary `json:"summary,omitempty"`
	Error      string           `json:"error,omitempty"`
}

func main() {
	asJSON := flag.Bool("json", false, "print one JSON object per file")
	flag.Usage = func() {
		fmt.Fprintln(flag.CommandLine.Output(), "usage: fitinspect [-json] <file|dir|zip>...")
		flag.PrintDefaults()
	}
	flag.Parse()
	if flag.NArg() == 0 {
		flag.Usage()
		os.Exit(2)
	}

	var entries []entry
	for _, root := range flag.Args() {
		err := fitfile.Walk(root, func(src fitfile.Source, r io.Reader) error {
			e := entry{Source: src.Path, FileNumber: src.FileNumber}
			if s, err := fitfile.Parse(r); err != nil {
				e.Error = err.Error()
				e.Skipped = errors.Is(err, fitfile.ErrNotActivity)
			} else {
				e.Summary = &s
			}
			entries = append(entries, e)
			return nil
		})
		if err != nil {
			fmt.Fprintf(os.Stderr, "fitinspect: %s: %v\n", root, err)
			os.Exit(1)
		}
	}

	if *asJSON {
		enc := json.NewEncoder(os.Stdout)
		for _, e := range entries {
			_ = enc.Encode(e)
		}
		return
	}
	printTable(os.Stdout, entries)
}

func printTable(out io.Writer, entries []entry) {
	tw := tabwriter.NewWriter(out, 0, 0, 2, ' ', 0)
	fmt.Fprintln(tw, "START (UTC)\tSPORT\tKM\tDAUER\tHM\tREC\tGPS\tHF\tWATT\tKEY\tQUELLE")
	byKey := map[string][]string{}
	failed, skipped := 0, 0
	for _, e := range entries {
		if e.Skipped {
			skipped++
			continue
		}
		if e.Summary == nil {
			failed++
			fmt.Fprintf(tw, "–\t–\t–\t–\t–\t–\t–\t–\t–\tFEHLER: %s\t%s\n", e.Error, e.Source)
			continue
		}
		s := e.Summary
		byKey[s.Key] = append(byKey[s.Key], e.Source)
		fmt.Fprintf(tw, "%s\t%s\t%.1f\t%s\t%d\t%d\t%d\t%s\t%s\t%s\t%s\n",
			s.StartTime.Format("2006-01-02 15:04"), sport(s), s.DistanceM/1000,
			fmtDuration(s), s.AscentM, s.Records, s.GPSPoints,
			yesNo(s.HasHR), yesNo(s.HasPower), s.Key, e.Source)
	}
	_ = tw.Flush()

	fmt.Fprintf(out, "\nDateien: %d · Aktivitäten: %d · keine Aktivität (übersprungen): %d · Fehler: %d · eindeutige Aufzeichnungen: %d\n",
		len(entries), len(entries)-failed-skipped, skipped, failed, len(byKey))

	var dupKeys []string
	for k, srcs := range byKey {
		if len(srcs) > 1 {
			dupKeys = append(dupKeys, k)
		}
	}
	sort.Strings(dupKeys)
	for _, k := range dupKeys {
		fmt.Fprintf(out, "Mehrfach vorhanden %s:\n", k)
		for _, src := range byKey[k] {
			fmt.Fprintf(out, "  %s\n", src)
		}
	}
}

func sport(s *fitfile.Summary) string {
	switch {
	case s.Sport == "":
		return "?"
	case s.SubSport == "" || s.SubSport == "generic":
		return s.Sport
	}
	return s.Sport + "/" + s.SubSport
}

// fmtDuration prefers the timer time (without pauses) and falls back to the
// elapsed time for files without a usable session.
func fmtDuration(sum *fitfile.Summary) string {
	seconds := sum.TimerS
	if seconds == 0 {
		seconds = sum.ElapsedS
	}
	s := int(seconds)
	return fmt.Sprintf("%d:%02d:%02d", s/3600, s/60%60, s%60)
}

func yesNo(b bool) string {
	if b {
		return "ja"
	}
	return "–"
}
